def find_target() -> Path:
    desktop = Path.home() / "Desktop"
    folder = next(p for p in desktop.iterdir() if p.is_dir() and (p / TARGET_NAME).exists())
    return folder / TARGET_NAME


def normalize_text(text: str) -> str:
    return " ".join(text.replace("\r", " ").split())


def set_paragraph_text(paragraph, text: str) -> None:
    for run in paragraph.runs:
        run.text = ""
    if paragraph.runs:
        paragraph.runs[0].text = text
    else:
        paragraph.add_run(text)


def delete_paragraph(paragraph) -> None:
    element = paragraph._element
    parent = element.getparent()
    if parent is not None:
        parent.remove(element)


def replace_cell_text(cell, text: str) -> None:
    if not cell.paragraphs:
        cell.text = text
        return
    for p in cell.paragraphs:
        set_paragraph_text(p, "")
    set_paragraph_text(cell.paragraphs[0], text)


def apply_front_replacements(doc: Document) -> None:
    for paragraph in doc.paragraphs:
        text = normalize_text(paragraph.text)
        if text in FRONT_REPLACEMENTS:
            set_paragraph_text(paragraph, FRONT_REPLACEMENTS[text])


def apply_global_replacements(doc: Document) -> None:
    for paragraph in doc.paragraphs:
        text = normalize_text(paragraph.text)
        if not text:
            continue
        new_text = GLOBAL_REPLACEMENTS.get(text, text)
        new_text = new_text.replace("—", ", ").replace("–", "-")
        if new_text != text:
            set_paragraph_text(paragraph, new_text)

    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                text = normalize_text(cell.text)
                if not text:
                    continue
                new_text = GLOBAL_REPLACEMENTS.get(text, text)
                new_text = new_text.replace("—", ", ").replace("–", "-")
                if new_text != text:
                    replace_cell_text(cell, new_text)


def polish_sections(doc: Document) -> None:
    current_section = None
    section_state: dict[str, dict[str, int]] = {}
    to_delete = []

    for paragraph in doc.paragraphs:
        text = normalize_text(paragraph.text)
        if not text:
            continue

        if text in SECTION_TEXT:
            current_section = text
            section_state.setdefault(current_section, {"boiler": 0, "extra": 0})
            continue

        if current_section is None:
            continue

        state = section_state[current_section]
        replacements = SECTION_TEXT[current_section]

        if text in BOILERPLATE:
            idx = state["boiler"]
            if idx < 5:
                set_paragraph_text(paragraph, replacements[idx])
            else:
                to_delete.append(paragraph)
            state["boiler"] += 1
            continue

        if text.startswith("В контексте раздела «") or text.startswith("Практическая проверка компонента "):
            idx = state["extra"]
            repl_idx = 5 + idx
            if repl_idx < len(replacements):
                set_paragraph_text(paragraph, replacements[repl_idx])
            else:
                to_delete.append(paragraph)
            state["extra"] += 1
            continue

    for paragraph in reversed(to_delete):
        delete_paragraph(paragraph)


def main() -> None:
    target = find_target()
    backup = target.with_name(f"{target.stem}_backup_style_{datetime.now():%Y%m%d_%H%M%S}{target.suffix}")
    shutil.copy2(target, backup)

    doc = Document(target)
    apply_front_replacements(doc)
    polish_sections(doc)
    apply_global_replacements(doc)
    doc.save(target)
    print(target)
    print(backup)


if __name__ == "__main__":
    main()
